import math

import torch
from torch import Tensor

PARALLEL_THRESHOLD = 1e-4


def slerp_tensor(a: Tensor, b: Tensor, t: float) -> Tensor:
    if a.shape != b.shape:
        raise ValueError(f"shape mismatch: {tuple(a.shape)} vs {tuple(b.shape)}")
    a32 = a.float().flatten()
    b32 = b.float().flatten()
    dot = float(torch.dot(a32, b32).item())
    if dot < 0.0:
        b32 = -b32
        dot = -dot
    norm_a = float(torch.linalg.vector_norm(a32).item())
    norm_b = float(torch.linalg.vector_norm(b32).item())
    if norm_a == 0.0 or norm_b == 0.0:
        return torch.lerp(a32, b32, t).reshape(a.shape).to(a.dtype)
    cosine = max(-1.0, min(1.0, dot / (norm_a * norm_b)))
    theta = math.acos(cosine)
    if theta < PARALLEL_THRESHOLD:
        return torch.lerp(a32, b32, t).reshape(a.shape).to(a.dtype)
    sin_theta = math.sin(theta)
    weight_a = math.sin((1.0 - t) * theta) / sin_theta
    weight_b = math.sin(t * theta) / sin_theta
    return (weight_a * a32 + weight_b * b32).reshape(a.shape).to(a.dtype)


def slerp_state_dicts(
    state_a: dict[str, Tensor], state_b: dict[str, Tensor], t: float
) -> dict[str, Tensor]:
    if state_a.keys() != state_b.keys():
        raise ValueError("state dicts have different keys, cannot merge")
    merged: dict[str, Tensor] = {}
    for key, tensor_a in state_a.items():
        tensor_b = state_b[key]
        if tensor_a.is_floating_point() and tensor_b.is_floating_point():
            merged[key] = slerp_tensor(tensor_a, tensor_b, t)
        else:
            merged[key] = tensor_a.clone()
    return merged

import math
from collections.abc import Callable
from dataclasses import dataclass

from torch import Tensor

from src.mythosmini.benchmarks.runner import BenchmarkScores
from src.mythosmini.config import SLERP_MAX_GENERATIONS, SLERP_T_SWEEP, SLERP_TOP_K
from src.mythosmini.merging.slerp import slerp_state_dicts

STALL_GENERATIONS = 3
SHARED_STEP_SKIP_RATIO = 0.5


@dataclass
class MergeCandidate:
    name: str
    state: dict[str, Tensor]
    steps: frozenset[int]
    scores: BenchmarkScores


Evaluator = Callable[[str, dict[str, Tensor]], BenchmarkScores]


def improves_any_category(child: BenchmarkScores, best: BenchmarkScores) -> bool:
    return child.blimp > best.blimp or child.arc > best.arc or child.wiki_ppl < best.wiki_ppl


def category_best(candidates: list[MergeCandidate]) -> BenchmarkScores:
    return BenchmarkScores(
        wiki_ppl=min(candidate.scores.wiki_ppl for candidate in candidates),
        blimp=max(candidate.scores.blimp for candidate in candidates),
        arc=max(candidate.scores.arc for candidate in candidates),
    )


def normalized_averages(candidates: list[MergeCandidate]) -> list[float]:
    blimps = [candidate.scores.blimp for candidate in candidates]
    arcs = [candidate.scores.arc for candidate in candidates]
    wiki_logs = [-math.log(max(candidate.scores.wiki_ppl, 1e-9)) for candidate in candidates]

    def normalize(values: list[float]) -> list[float]:
        low, high = min(values), max(values)
        if high == low:
            return [0.5] * len(values)
        return [(value - low) / (high - low) for value in values]

    columns = [normalize(blimps), normalize(arcs), normalize(wiki_logs)]
    return [sum(column[index] for column in columns) / 3.0 for index in range(len(candidates))]


def select_diverse(candidates: list[MergeCandidate], keep: int) -> list[MergeCandidate]:
    if not candidates:
        return []
    diverse: dict[str, MergeCandidate] = {}
    wiki_best = min(candidates, key=lambda c: c.scores.wiki_ppl)
    diverse[wiki_best.name] = wiki_best
    blimp_best = max(candidates, key=lambda c: c.scores.blimp)
    diverse[blimp_best.name] = blimp_best
    arc_best = max(candidates, key=lambda c: c.scores.arc)
    diverse[arc_best.name] = arc_best
    averages = normalized_averages(candidates)
    order = sorted(range(len(candidates)), key=lambda i: averages[i], reverse=True)
    for index in order:
        if len(diverse) >= keep:
            break
        candidate = candidates[index]
        if candidate.name not in diverse:
            diverse[candidate.name] = candidate
    final_list = list(diverse.values())
    final_averages = normalized_averages(final_list)
    final_order = sorted(range(len(final_list)), key=lambda i: final_averages[i], reverse=True)
    return [final_list[index] for index in final_order]


def build_centroid_merge(
    parents: list[MergeCandidate], generation: int, evaluate: Evaluator
) -> MergeCandidate | None:
    if len(parents) < 3:
        return None
    a, b, c = parents[0], parents[1], parents[2]
    state_ab = slerp_state_dicts(a.state, b.state, 0.5)
    name_abc = f"gen{generation}_centroid_{a.name}+{b.name}+{c.name}"
    state_abc = slerp_state_dicts(state_ab, c.state, 0.33)
    scores = evaluate(name_abc, state_abc)
    return MergeCandidate(
        name=name_abc, state=state_abc, steps=a.steps | b.steps | frozenset(c.steps), scores=scores
    )


def shares_too_many_steps(a: MergeCandidate, b: MergeCandidate) -> bool:
    if not a.steps or not b.steps:
        return False
    highest_a, highest_b = max(a.steps), max(b.steps)
    if highest_a == 0 or highest_b == 0:
        return False
    return min(highest_a, highest_b) / max(highest_a, highest_b) > SHARED_STEP_SKIP_RATIO


def merge_pair(
    a: MergeCandidate, b: MergeCandidate, t: float, generation: int, evaluate: Evaluator
) -> MergeCandidate:
    name = f"gen{generation}_{a.name}+{b.name}@t{t:.2f}"
    state = slerp_state_dicts(a.state, b.state, t)
    scores = evaluate(name, state)
    return MergeCandidate(name=name, state=state, steps=a.steps | b.steps, scores=scores)


def eligible_pairs(
    parents: list[MergeCandidate], generation: int
) -> list[tuple[MergeCandidate, MergeCandidate]]:
    all_pairs = [
        (parents[first_index], parents[second_index])
        for first_index in range(len(parents))
        for second_index in range(first_index + 1, len(parents))
    ]
    if generation != 0:
        return all_pairs
    filtered = []
    for a, b in all_pairs:
        is_outstanding_a = a.scores.blimp > 58 or a.scores.arc > 30 or a.scores.wiki_ppl < 4.5
        is_outstanding_b = b.scores.blimp > 58 or b.scores.arc > 30 or b.scores.wiki_ppl < 4.5
        if is_outstanding_a and is_outstanding_b:
            filtered.append((a, b))
            continue
        if not shares_too_many_steps(a, b):
            filtered.append((a, b))
    return filtered if filtered else all_pairs


def build_generation(
    parents: list[MergeCandidate], generation: int, evaluate: Evaluator
) -> list[MergeCandidate]:
    children: list[MergeCandidate] = []
    for first, second in eligible_pairs(parents, generation):
        for t in SLERP_T_SWEEP:
            children.append(merge_pair(first, second, t, generation, evaluate))
    wiki_best = min(parents, key=lambda c: c.scores.wiki_ppl)
    arc_best = max(parents, key=lambda c: c.scores.arc)
    blimp_best = max(parents, key=lambda c: c.scores.blimp)
    for t in (0.33, 0.5, 0.66):
        children.append(merge_pair(wiki_best, arc_best, t, generation, evaluate))
        children.append(merge_pair(wiki_best, blimp_best, t, generation, evaluate))
        children.append(merge_pair(arc_best, blimp_best, t, generation, evaluate))
    centroid = build_centroid_merge(parents, generation, evaluate)
    if centroid:
        children.append(centroid)
    return children


def aggregate_score(
    scores: BenchmarkScores,
    blimp_ref: tuple[float, float],
    arc_ref: tuple[float, float],
    wiki_log_ref: tuple[float, float],
) -> float:
    def normalize(val: float, ref: tuple[float, float]) -> float:
        if ref[1] == ref[0]:
            return 0.5
        return (val - ref[0]) / (ref[1] - ref[0])

    blimp_n = normalize(scores.blimp, blimp_ref)
    arc_n = normalize(scores.arc, arc_ref)
    wiki_log = -math.log(max(scores.wiki_ppl, 1e-9))
    wiki_n = normalize(wiki_log, wiki_log_ref)
    return (blimp_n + arc_n + wiki_n) / 3.0


def run_tournament(
    seeds: list[MergeCandidate],
    evaluate: Evaluator,
    log: Callable[[str], None],
) -> MergeCandidate:
    if not seeds:
        raise ValueError("tournament needs at least one seed candidate")

    blimps = [s.scores.blimp for s in seeds]
    arcs = [s.scores.arc for s in seeds]
    wiki_logs = [-math.log(max(s.scores.wiki_ppl, 1e-9)) for s in seeds]
    b_ref = (min(blimps), max(blimps))
    a_ref = (min(arcs), max(arcs))
    w_ref = (min(wiki_logs), max(wiki_logs))

    population = select_diverse(seeds, SLERP_TOP_K)
    best_overall = population[0]
    best_score = aggregate_score(best_overall.scores, b_ref, a_ref, w_ref)
    best_average = max(normalized_averages(population))
    stalled = 0

    for generation in range(SLERP_MAX_GENERATIONS):
        if len(population) < 2:
            log(f"tournament stopped: single candidate after generation {generation}")
            break
        previous_best = category_best(population)
        children = build_generation(population, generation, evaluate)
        if not children:
            log(f"tournament stopped: no eligible pairs in generation {generation}")
            break

        for child in children:
            score = aggregate_score(child.scores, b_ref, a_ref, w_ref)
            if score > best_score:
                best_score = score
                best_overall = child

        if not any(improves_any_category(child.scores, previous_best) for child in children):
            log(f"tournament stopped: generation {generation} children worse in all categories")
            break

        population = select_diverse(population + children, SLERP_TOP_K)
        current_best = max(normalized_averages(population))
        stalled = stalled + 1 if current_best <= best_average else 0
        best_average = max(best_average, current_best)
        log(f"generation {generation}: population {len(population)}, stalled {stalled}")
        if stalled >= STALL_GENERATIONS:
            log("tournament stopped: no improvement for three generations")
            break
    return best_overall

